input.new_string:
/**
 * Pending invites hold a seat, so the seat quota counts them. Revoked or
 * expired invitations are not pending and free their seat immediately.
 */
export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        gt(invitations.expiresAt, toIsoTimestamp(new Date())),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** Case-insensitive lookup used by the duplicate-invite and accept checks. */
export async function findPendingInvitationByEmail(
  orgId: OrgId,
  email: string,
): Promise<Invitation | null> {
  const pending = await listPendingInvitations(orgId);
  const now = toIsoTimestamp(new Date());
  const match = pending.find(
    (row) =>
      row.email.toLowerCase() === email.toLowerCase() && row.expiresAt > now,
  );
  return match ?? null;
}

